          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.metrics import accuracy_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.tree import DecisionTreeClassifier\n\n# Structural Risk Minimization (SRM) + Uji Korelasi Rademacher (Random Labels)\nX, y = make_classification(\n    n_samples=600, n_features=20, n_informative=6, n_redundant=4,\n    flip_y=0.10, class_sep=1.1, random_state=42\n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.35, random_state=42)\n\nrng = np.random.default_rng(123)\ny_rand = rng.integers(0, 2, size=len(y_tr))  # label acak murni (uji Rademacher)\n\nprint(\"SRM pada Hirarki Pohon Keputusan (max_depth): True Signal vs Random Noise Fit\")\nprint(\"-\" * 78)\nprint(f\"{'max_depth':>9} | {'Train Acc':>10} | {'Test Acc':>10} | {'Gen Gap':>9} | {'Random-Label Fit':>16} | {'Rademacher Proxy':>16}\")\nprint(\"-\" * 78)\n\nfor depth in [1, 2, 4, 6, 10, 20]:\n    clf_real = DecisionTreeClassifier(max_depth=depth, random_state=42).fit(X_tr, y_tr)\n    tr_acc = accuracy_score(y_tr, clf_real.predict(X_tr))\n    te_acc = accuracy_score(y_te, clf_real.predict(X_te))\n    gap = tr_acc - te_acc\n\n    clf_noise = DecisionTreeClassifier(max_depth=depth, random_state=42).fit(X_tr, y_rand)\n    noise_acc = accuracy_score(y_rand, clf_noise.predict(X_tr))\n    # Korelasi Rademacher ~ 2 * noise_acc - 1 (0 = tidak bisa menghafal noise, 1 = hafal 100%)\n    rad_proxy = 2.0 * noise_acc - 1.0\n\n    print(f\"{depth:>9d} | {tr_acc:>10.4f} | {te_acc:>10.4f} | {gap:>+9.4f} | {noise_acc:>16.4f} | {rad_proxy:>16.4f}\")",
          "expectedOutput": "SRM pada Hirarki Pohon Keputusan (max_depth): True Signal vs Random Noise Fit\n------------------------------------------------------------------------------\nmax_depth |  Train Acc |   Test Acc |   Gen Gap | Random-Label Fit | Rademacher Proxy\n------------------------------------------------------------------------------\n        1 |     0.7974 |     0.7476 |   +0.0498 |           0.5333 |           0.0667\n        2 |     0.8410 |     0.7857 |   +0.0553 |           0.5641 |           0.1282\n        4 |     0.8897 |     0.7952 |   +0.0945 |           0.5872 |           0.1744\n        6 |     0.9410 |     0.7762 |   +0.1648 |           0.6385 |           0.2769\n       10 |     1.0000 |     0.7810 |   +0.2190 |           0.7846 |           0.5692\n       20 |     1.0000 |     0.7810 |   +0.2190 |           1.0000 |           1.0000",
