          "code": "import numpy as np\nfrom sklearn.kernel_approximation import RBFSampler\nfrom sklearn.linear_model import Ridge, RidgeCV\nfrom sklearn.metrics import mean_squared_error\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\n# Scikit-Learn Modern: Ridgeless (alpha=1e-10) vs RidgeCV Optimal Lintas Kapasitas RFF\nrng = np.random.default_rng(101)\nn_train, n_test, d_in = 80, 500, 8\n\ndef make_nonlinear_target(X):\n    return 2.0 * np.sin(X[:, 0]) + 1.5 * np.cos(X[:, 1]) - 0.8 * X[:, 2] * X[:, 3]\n\nX_tr = rng.normal(0.0, 1.0, size=(n_train, d_in))\nX_te = rng.normal(0.0, 1.0, size=(n_test, d_in))\ny_tr = make_nonlinear_target(X_tr) + rng.normal(0.0, 0.35, size=n_train)\ny_te = make_nonlinear_target(X_te) + rng.normal(0.0, 0.35, size=n_test)\n\nalphas = np.logspace(-4, 3, 29)\n\nprint(f\"Bukti Eliminasi Puncak Double Descent via RidgeCV (RBFSampler, n_train={n_train})\")\nprint(\"-\" * 78)\nprint(f\"{'n_comp (p)':>10} | {'p/n':>6} | {'Ridgeless Test MSE':>18} | {'RidgeCV Test MSE':>16} | {'alpha* terpilih':>15}\")\nprint(\"-\" * 78)\n\nfor p in [10, 35, 70, 80, 90, 160, 320, 600]:\n    pipe_zero = make_pipeline(\n        StandardScaler(),\n        RBFSampler(gamma=0.12, n_components=p, random_state=42),\n        Ridge(alpha=1e-10, solver=\"svd\"),\n    )\n    pipe_cv = make_pipeline(\n        StandardScaler(),\n        RBFSampler(gamma=0.12, n_components=p, random_state=42),\n        RidgeCV(alphas=alphas),\n    )\n    pipe_zero.fit(X_tr, y_tr)\n    pipe_cv.fit(X_tr, y_tr)\n\n    mse_zero = mean_squared_error(y_te, pipe_zero.predict(X_te))\n    mse_cv = mean_squared_error(y_te, pipe_cv.predict(X_te))\n    best_a = float(pipe_cv.named_steps[\"ridgecv\"].alpha_)\n    print(f\"{p:>10d} | {p/n_train:>6.2f} | {mse_zero:>18.4f} | {mse_cv:>16.4f} | {best_a:>15.4g}\")",
