          "code": "import numpy as np\n\n# Diagnostik Spektral: Verifikasi Hukum Varians Marchenko-Pastur di Kiri & Kanan p = n\n# Kovarians isotropik Sigma = I_p, n = 80, noise sigma_eps = 0.5 (sigma^2 = 0.25)\nrng = np.random.default_rng(2025)\nn = 80\nsigma_eps = 0.5\nsigma2 = sigma_eps ** 2\nn_rep = 60\n\nprint(f\"Verifikasi Empiris vs Teori Asimtotik Varians Isotropik (n={n}, sigma^2={sigma2:.2f})\")\nprint(\"-\" * 76)\nprint(f\"{'p':>5} | {'gamma=p/n':>9} | {'Empiris Var(noise)':>18} | {'Teori Asimtotik':>16} | {'Status Zona':<16}\")\nprint(\"-\" * 76)\n\nfor p in [20, 40, 64, 76, 84, 100, 160, 320]:\n    gamma = p / n\n    var_samples = []\n    for _ in range(n_rep):\n        X = rng.normal(0.0, 1.0, size=(n, p))\n        eps = rng.normal(0.0, sigma_eps, size=n)\n        # Error prediksi murni akibat noise: delta_w = X^+ eps; E[(x_new^T delta_w)^2] = ||delta_w||^2\n        delta_w = np.linalg.pinv(X) @ eps\n        var_samples.append(float(np.sum(delta_w ** 2)))\n    emp_var = float(np.mean(var_samples))\n    if gamma < 1.0:\n        theo_var = sigma2 * (gamma / (1.0 - gamma))\n    else:\n        theo_var = sigma2 * (1.0 / (gamma - 1.0))\n\n    zone = \"DANGER PEAK!\" if 0.85 <= gamma <= 1.15 else (\"Underparam\" if gamma < 0.85 else \"Overparam\")\n    print(f\"{p:>5d} | {gamma:>9.2f} | {emp_var:>18.4f} | {theo_var:>16.4f} | {zone:<16}\")",
