          "code": "import numpy as np\n\n# Pembuktian Empiris: Implicit Regularization Gradient Descent (w_0 = 0 -> Minimum L2-Norm)\nrng = np.random.default_rng(42)\nn, p = 40, 160  # overparameterized (p = 4n)\n\n# Sinyal sejati hidup di 5 koordinat awal (rendah-norm)\nw_true = np.zeros(p)\nw_true[:5] = [1.5, -1.0, 0.8, -0.6, 0.5]\n\nX_tr = rng.normal(0.0, 1.0 / np.sqrt(n), size=(n, p))\nX_te = rng.normal(0.0, 1.0 / np.sqrt(n), size=(300, p))\ny_tr = X_tr @ w_true + rng.normal(0.0, 0.05, size=n)\ny_te = X_te @ w_true\n\n# 1. Solusi Analitik Minimum-L2-Norm: w_MN = X^T (X X^T)^-1 y\nw_mn = X_tr.T @ np.linalg.solve(X_tr @ X_tr.T, y_tr)\n\n# 2. Gradient Descent murni dari w_0 = 0 (tanpa penalti eksplisit apa pun!)\nL_smooth = float(np.linalg.norm(X_tr, ord=2) ** 2)\neta = 0.9 / L_smooth\nw_gd_zero = np.zeros(p)\nfor _ in range(1500):\n    w_gd_zero -= eta * (X_tr.T @ (X_tr @ w_gd_zero - y_tr))\n\n# 3. Gradient Descent dari inisialisasi besar w_0 ~ N(0, 0.5^2 I) -> komponen null-space bertahan!\nw_init_big = rng.normal(0.0, 0.5, size=p)\nw_gd_big = w_init_big.copy()\nfor _ in range(1500):\n    w_gd_big -= eta * (X_tr.T @ (X_tr @ w_gd_big - y_tr))\n\n# Proyeksi komponen null-space dari w_init_big\nP_row = X_tr.T @ np.linalg.pinv(X_tr.T)\nnull_component_init = w_init_big - P_row @ w_init_big\nnull_component_final = w_gd_big - P_row @ w_gd_big\n\nprint(\"Audit Implicit Bias Gradient Descent pada Rezim Overparameterized (n=40, p=160)\")\nprint(\"-\" * 76)\nfor label, w in [\n    (\"Analitik Min-Norm (X^+ y)\", w_mn),\n    (\"GD dari w_0 = 0 (1500 step)\", w_gd_zero),\n    (\"GD dari w_0 ~ N(0, 0.5^2 I)\", w_gd_big),\n]:\n    tr_mse = float(np.mean((X_tr @ w - y_tr) ** 2))\n    te_mse = float(np.mean((X_te @ w - y_te) ** 2))\n    print(f\"{label:<28} | Train MSE={tr_mse:.2e} | Test MSE={te_mse:.5f} | ||w||_2={np.linalg.norm(w):.4f}\")\n\nprint(\"-\" * 76)\nprint(f\"Jarak ||w_GD(0) - w_MN||_2               = {np.linalg.norm(w_gd_zero - w_mn):.3e}\")\nprint(f\"Norm Null-Space Awal vs Akhir (GD besar) = {np.linalg.norm(null_component_init):.4f} vs {np.linalg.norm(null_component_final):.4f} (INVARIANT!)\")",
