          "code": "import numpy as np\nfrom scipy.optimize import curve_fit\n\n# Diagnostik Ekonomi Produksi: Power-Law Scaling Laws vs Ekstrapolasi Linier Biaya Pelabelan\n# Ground truth tersembunyi: L(N) = 0.065 + 2.40 * N^(-0.38)\nN_pilot = np.array([500, 1200, 2500, 5000, 10000, 20000], dtype=float)\nrng = np.random.default_rng(14)\nL_true_fn = lambda N: 0.065 + 2.40 * (N ** -0.38)\nL_obs = L_true_fn(N_pilot) + rng.normal(0.0, 0.0015, size=len(N_pilot))\n\ndef power_law(N, L_inf, c, alpha):\n    return L_inf + c * np.power(N, -alpha)\n\npopt, _ = curve_fit(\n    power_law, N_pilot, L_obs,\n    p0=[0.05, 2.0, 0.35],\n    bounds=([0.0, 0.0, 0.05], [0.5, 50.0, 1.5]),\n    maxfev=10000,\n)\nL_inf_hat, c_hat, alpha_hat = [float(v) for v in popt]\n\n# Ekstrapolasi linier naif dari dua titik pilot terakhir (10k -> 20k)\nslope_naive = (L_obs[-1] - L_obs[-2]) / (N_pilot[-1] - N_pilot[-2])\n\n# Ekonomi bisnis: biaya pelabelan $0.50 / sampel; tiap -1% error bernilai $85,000 / tahun\ncost_per_label = 0.50\nvalue_per_pct_error = 85000.0\nbase_N = N_pilot[-1]\nbase_L = power_law(base_N, L_inf_hat, c_hat, alpha_hat)\n\nprint(f\"Estimasi Scaling Law: L(N) = {L_inf_hat:.4f} + {c_hat:.3f} * N^(-{alpha_hat:.3f})\")\nprint(f\"Faktor pengali data untuk memotong separuh reducible error (2^(1/alpha)): {2**(1/alpha_hat):.2f}x\")\nprint(\"-\" * 82)\nprint(f\"{'Target N':>9} | {'Pred Linier':>11} | {'Pred PowerLaw':>13} | {'Biaya Label':>11} | {'Nilai Error':>11} | {'Net ROI':>11}\")\nprint(\"-\" * 82)\n\nfor N_target in [40000, 80000, 160000, 320000]:\n    pred_lin = max(0.0, float(L_obs[-1] + slope_naive * (N_target - base_N)))\n    pred_pl = float(power_law(N_target, L_inf_hat, c_hat, alpha_hat))\n    added_samples = N_target - base_N\n    label_cost = added_samples * cost_per_label\n    error_drop_pct = (base_L - pred_pl) * 100.0\n    biz_val = error_drop_pct * value_per_pct_error\n    net_roi = biz_val - label_cost\n    print(f\"{N_target:>9,d} | {pred_lin*100:>10.2f}% | {pred_pl*100:>12.2f}% | ${label_cost:>10,.0f} | ${biz_val:>10,.0f} | ${net_roi:>+10,.0f}\")",
